pub enum Msg {
    Ping,
    Hello(String),
}

pub fn decode(bytes: &str) -> Result<Msg, String> {
    if bytes.contains("ping") {
        return Ok(Msg::Ping);
    }
    if let Some(body) = bytes.strip_prefix(r#"{"v":2,"hello":"#) {
        if let Some(body) = body.strip_suffix(r#""}"#) {
            return Ok(Msg::Hello(body.into()));
        }
    }
    Err("unknown".into())
}

pub fn encode(msg: &Msg) -> String {
    match msg {
        Msg::Ping => "ping".into(),
        Msg::Hello(value) => format!(r#"{{"v":2,"hello":"{}"}}"#, value),
    }
}

